<script setup>
import { ref } from 'vue';
import axios from 'axios';
import { Head, Link, useForm } from '@inertiajs/vue3';
import { ArrowLeft, BookOpen, Plus } from 'lucide-vue-next';
import AdminLayout from '@/Layouts/AdminLayout.vue';
import Button from '@/Components/UI/Button.vue';
import Input from '@/Components/UI/Input.vue';
import Modal from '@/Components/UI/Modal.vue';
import SimplePagination from '@/Components/UI/SimplePagination.vue';
defineOptions({ layout: AdminLayout });
const props = defineProps({ organization: Object, licenses: Object });
const open = ref(false), editing = ref(null), query = ref(''), results = ref([]), searching = ref(false), searchError = ref(''), searched = ref(false);
const form = useForm({ course_id: '', quantity: 1, expires_at: '', status: 'active', reason: '' });
const edit = (license = null) => { editing.value = license; form.reset(); form.clearErrors(); if (license) { form.course_id = license.course_id; form.quantity = license.quantity; form.expires_at = license.expires_at || ''; form.status = license.status; form.reason = license.reason || ''; } results.value = []; query.value = ''; searched.value = false; open.value = true; };
const search = async () => { if (query.value.trim().length < 2 || searching.value) return; searching.value = true; searchError.value = ''; searched.value = false; try { results.value = (await axios.get('/admin/organization-license-courses', { params: { search: query.value.trim() }, timeout: 20000 })).data.courses; searched.value = true; } catch { searchError.value = 'Could not search courses. Try again.'; } finally { searching.value = false; } };
const save = () => form.submit(editing.value ? 'patch' : 'post', `/admin/organizations/${props.organization.id}/licenses${editing.value ? `/${editing.value.id}` : ''}`, { preserveScroll: true, onSuccess: () => { open.value = false; } });
</script>
<template>
    <Head :title="`Course allocations: ${organization.name}`" />
    <div class="mx-auto max-w-6xl space-y-6"><Link :href="`/admin/organizations/${organization.id}/edit`" class="inline-flex items-center gap-2 text-sm text-surface-500"><ArrowLeft class="h-4 w-4" /> Manage organization</Link><header class="flex flex-wrap items-start justify-between gap-4"><div><p class="text-xs font-semibold uppercase tracking-widest text-primary-700">{{ organization.name }}</p><h1 class="mt-2 text-3xl font-display font-bold">Course allocations</h1><p class="mt-2 max-w-2xl text-sm text-surface-500">Grant course places to this company or manage its existing licenses. The organization administrator assigns those places to learners.</p></div><Button :disabled="!organization.is_active" @click="edit()"><Plus class="h-4 w-4" /> Allocate course</Button></header>
        <div class="rounded-xl border border-primary-100 bg-primary-50 p-4 text-sm leading-relaxed text-primary-900">A manual allocation grants access without collecting a payment. Record why it is being granted. Purchased licenses retain their original quantity and terms; allocate additional places separately.</div>
        <div v-if="licenses.data.length" class="space-y-3"><article v-for="license in licenses.data" :key="license.id" class="flex flex-wrap items-center gap-5 rounded-2xl border border-surface-200 bg-white p-5"><div class="rounded-xl bg-surface-50 p-3 text-primary-700"><BookOpen class="h-6 w-6" /></div><div class="min-w-0 flex-1"><p class="font-semibold">{{ license.course?.title || 'Archived course' }}</p><p class="mt-1 text-xs text-surface-500">License #{{ license.id }} · {{ license.purchased ? 'Purchased' : 'Allocated' }} · {{ license.active ? 'Active' : 'Unavailable' }}</p><p class="mt-2 text-sm text-surface-500">{{ license.expires_at ? `Expires ${license.expires_at}` : 'No scheduled expiry' }}</p></div><div class="text-right"><p class="text-xl font-bold">{{ license.used }} / {{ license.quantity }}</p><p class="text-xs text-surface-500">places assigned</p></div><Button variant="secondary" @click="edit(license)">Manage</Button></article></div>
        <div v-else class="rounded-2xl border border-dashed border-surface-300 bg-white p-14 text-center"><BookOpen class="mx-auto h-10 w-10 text-surface-300" /><h2 class="mt-4 font-semibold">No course places allocated yet</h2><p class="mt-2 text-sm text-surface-500">Allocate a published course or let the organization administrator purchase places.</p></div><SimplePagination :page="licenses" />
    </div>
    <Modal :show="open" :title="editing ? 'Manage course allocation' : 'Allocate a course'" :closeable="!form.processing" @close="open = false"><form @submit.prevent="save" class="space-y-5">
        <template v-if="!editing"><div class="flex items-end gap-2"><Input v-model="query" label="Find a published course" placeholder="At least 2 characters" class="min-w-0 flex-1" @keydown.enter.prevent="search" /><Button variant="secondary" :loading="searching" :disabled="query.trim().length < 2" @click="search">Search</Button></div><p v-if="searchError" role="alert" class="text-sm text-red-700">{{ searchError }}</p><label v-if="results.length" class="block text-sm font-semibold">Course<select v-model="form.course_id" required class="mt-2 block w-full rounded-xl border-surface-200"><option value="">Choose course</option><option v-for="course in results" :key="course.id" :value="course.id">{{ course.title }}</option></select></label><p v-if="searched && !results.length" role="status" class="text-sm text-surface-500">No published courses match your search.</p></template>
        <p v-else class="font-semibold">{{ editing.course?.title }}</p><Input v-model="form.quantity" type="number" min="1" max="1000000" label="Course places" :disabled="editing?.purchased" required :error="form.errors.quantity" /><Input v-model="form.expires_at" type="date" label="Access expiry (optional, through end of day)" :disabled="editing?.purchased" :error="form.errors.expires_at" />
        <label v-if="editing" class="block text-sm font-semibold">License status<select v-model="form.status" class="mt-2 block w-full rounded-xl border-surface-200"><option value="active">Active</option><option value="revoked">Revoked — stop license access</option></select></label><p v-if="editing && form.status === 'revoked'" class="rounded-xl bg-amber-50 p-3 text-sm text-amber-900">Revocation stops all access derived from this allocation. Progress and earned certificates are retained.</p>
        <label class="block text-sm font-semibold">Reason / agreement reference<textarea v-model="form.reason" rows="3" minlength="5" maxlength="1000" required class="mt-2 block w-full rounded-xl border-surface-200" placeholder="e.g. Corporate training agreement reference" /></label><p v-for="(error, field) in form.errors" :key="field" role="alert" class="text-sm text-red-700">{{ error }}</p><div class="flex justify-end gap-3"><Button variant="secondary" :disabled="form.processing" @click="open = false">Cancel</Button><Button type="submit" :loading="form.processing" :disabled="!form.course_id">{{ editing ? 'Save changes' : 'Allocate places' }}</Button></div>
    </form></Modal>
</template>
